#include <HardwareSerial.h>

#define CRSF_BAUD      420000
#define OUT_BAUD       115200    // скорость UART для RS-485
#define MAX485_DE_RE   4         // пин управления передачей MAX485
#define CRSF_SYNC      0xC8
#define CRSF_FRAME_RC  0x16

HardwareSerial CrsfSerial(2);   // UART2 — приём CRSF
HardwareSerial OutSerial(1);    // UART1 — передача по RS-485

// ---------- CRC8 (DVB-S2, полином 0xD5) ----------
uint8_t crc8_d5(const uint8_t *data, uint8_t len) {
  uint8_t crc = 0;
  for (uint8_t i = 0; i < len; i++) {
    crc ^= data[i];
    for (uint8_t b = 0; b < 8; b++) {
      if (crc & 0x80)
        crc = (crc << 1) ^ 0xD5;
      else
        crc <<= 1;
    }
  }
  return crc;
}

// ---------- Распаковка 16 каналов из 22 байтов ----------
void unpackChannels(const uint8_t *payload, uint16_t *channels) {
  uint32_t bits = 0;
  uint8_t  bitCount = 0;
  uint8_t  byteIdx = 0;

  for (uint8_t ch = 0; ch < 16; ch++) {
    while (bitCount < 11) {
      bits |= (uint32_t)payload[byteIdx] << bitCount;
      bitCount += 8;
      byteIdx++;
    }
    channels[ch] = bits & 0x7FF;   // 11 бит
    bits >>= 11;
    bitCount -= 11;
  }
}

// ---------- Парсер ----------
enum ParseState { WAIT_SYNC, WAIT_LEN, WAIT_TYPE, READ_PAYLOAD, READ_CRC };
ParseState state = WAIT_SYNC;

uint8_t  frameLen = 0;
uint8_t  frameType = 0;
uint8_t  payload[62];
uint8_t  payloadIdx = 0;
uint8_t  crcByte = 0;

uint16_t channels[16];

void processCrsfByte(uint8_t b) {
  switch (state) {

    case WAIT_SYNC:
      if (b == CRSF_SYNC) state = WAIT_LEN;
      break;

    case WAIT_LEN:
      if (b < 2 || b > 62) { state = WAIT_SYNC; break; }  // некорректная длина
      frameLen = b;
      state = WAIT_TYPE;
      break;

    case WAIT_TYPE:
      frameType = b;
      payloadIdx = 0;
      // payload = frameLen - 2 (тип + CRC)
      if (frameLen <= 2) {
        // нет payload, сразу CRC
        state = READ_CRC;
      } else {
        state = READ_PAYLOAD;
      }
      break;

    case READ_PAYLOAD:
      payload[payloadIdx++] = b;
      if (payloadIdx == frameLen - 2) state = READ_CRC;
      break;

    case READ_CRC:
      crcByte = b;
      // Проверка CRC: по type + payload
      uint8_t buf[63];
      buf[0] = frameType;
      memcpy(buf + 1, payload, payloadIdx);
      if (crc8_crsf(buf, payloadIdx + 1) == crcByte) {
        // CRC верна — обрабатываем
        if (frameType == CRSF_FRAME_RC && payloadIdx == 22) {
          unpackChannels(payload, channels);
          sendViaRS485();
        }
      }
      state = WAIT_SYNC;
      break;
  }
}


// ---------- Отправка по RS-485 ----------
void sendViaRS485() {
  digitalWrite(MAX485_DE_RE, HIGH);

  uint8_t data[32];
  for (uint8_t i = 0; i < 16; i++) {
    data[i * 2]     = channels[i] & 0xFF;
    data[i * 2 + 1] = (channels[i] >> 8) & 0xFF;
  }

  uint8_t crc = crc8_d5(data, 32);

  OutSerial.write(0xAA);        // стартовый маркер
  OutSerial.write(0x21);        // длина блока (33 = 32 данные + 1 CRC)
  OutSerial.write(data, 32);    // данные
  OutSerial.write(crc);         // CRC8
  OutSerial.write(0x55);        // конечный маркер

  OutSerial.flush();
  digitalWrite(MAX485_DE_RE, LOW);
}

void setup() {
  CrsfSerial.begin(CRSF_BAUD, SERIAL_8N1, 16, 17);  // RX=16, TX=17
  OutSerial.begin(OUT_BAUD, SERIAL_8N1, 17, 4);      // TX=17 → DI MAX485
  pinMode(MAX485_DE_RE, OUTPUT);
  digitalWrite(MAX485_DE_RE, LOW);                   // старт — приём
}

void loop() {
  while (CrsfSerial.available()) {
    processCrsfByte(CrsfSerial.read());
  }
}
